import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long count = 0;
        boolean overflow = false;
        BigDecimal total = BigDecimal.ZERO;
        for (int i = 0; i < n; i++) {
            BigDecimal price = new BigDecimal(sc.next());
            long each = sc.nextLong();
            total = total.add(price.multiply(BigDecimal.valueOf(each)));
            if (!overflow) {
                try {
                    count = Math.addExact(count, each);
                } catch (ArithmeticException e) {
                    overflow = true;
                }
            }
        }
        System.out.println("count=" + (overflow ? "overflow" : String.valueOf(count)));
        System.out.println("total=" + total.setScale(2, RoundingMode.HALF_UP));
    }
}
